import React from "react";

import TicketCard from "./TicketCard";


function Sidebar({
    disputes,
    loading,
    onResolve,
    onRefresh
}) {


    /*
        Open tickets
    */
    const openTickets =
        disputes.filter(
            dispute =>
                dispute.status === "Open"
        );


    /*
        Resolved tickets
    */
    const resolvedTickets =
        disputes.filter(
            dispute =>
                dispute.status === "Resolved"
        );


    return (

        <aside className="sidebar">


            {/* Sidebar Header */}

            <div className="sidebar-header">


                <div>

                    <h3>
                        My Tickets
                    </h3>

                    <p>
                        Track your dispute requests
                    </p>

                </div>


                <button
                    className="refresh-button"
                    onClick={onRefresh}
                    title="Refresh tickets"
                >

                    ↻

                </button>


            </div>


            {/* Open Tickets */}

            <div className="ticket-section">


                <div className="section-title">


                    <span>
                        Open
                    </span>


                    <span
                        className="count open-count"
                    >

                        {openTickets.length}

                    </span>


                </div>


                {loading ? (

                    <div className="empty-state">

                        Loading...

                    </div>

                ) : openTickets.length === 0 ? (

                    <div className="empty-state">

                        No open disputes.

                    </div>

                ) : (

                    openTickets.map(
                        dispute => (

                            <TicketCard
                                key={dispute.id}
                                dispute={dispute}
                                onResolve={onResolve}
                            />

                        )
                    )

                )}


            </div>


            {/* Resolved Tickets */}

            <div className="ticket-section">


                <div className="section-title">


                    <span>
                        Resolved
                    </span>


                    <span
                        className="count resolved-count"
                    >

                        {resolvedTickets.length}

                    </span>


                </div>


                {resolvedTickets.length === 0 ? (

                    <div className="empty-state">

                        No resolved disputes.

                    </div>

                ) : (

                    resolvedTickets.map(
                        dispute => (

                            <TicketCard
                                key={dispute.id}
                                dispute={dispute}
                                onResolve={onResolve}
                            />

                        )
                    )

                )}


            </div>


        </aside>

    );

}


export default Sidebar;
